template <class LOCK>
class FileCache {
public:
    const char *find(const char *path) {
        std::lock_guard<LOCK> guard(lock_);   // Scoped Locking
        return find_i(path);                  // _i assumes the lock is held
    }
private:
    LOCK lock_;
    const char *find_i(const char *path);
};
using ThreadedCache = FileCache<std::mutex>;      // FileCache<NullMutex> single-threaded, <std::shared_mutex> C++17

