struct Lockable {
    virtual ~Lockable() = default;
    virtual void acquire() = 0;
    virtual void release() = 0;
};
class Lock {                       // Bridge handle: a Lockable used as an object
public:
    explicit Lock(Lockable &l) : lock_(l) {}
    void acquire() { lock_.acquire(); }
    void release() { lock_.release(); }
private:
    Lockable &lock_;
};
